import httpximport asynciofrom datetime import datetime, timezone#ConfigMAX_OPEN_BETS  = 5MAX_PLAYED_CAP = 20   # hard ceilingTRACKER_NAME   = "chukwuebuka"def _dynamic_max(losses: int) -> int:    """    Start at 10. First loss → 15. Two or more losses → 20 (hard cap).    """    if losses == 0:        return 10    elif losses == 1:        return 15    else:        return MAX_PLAYED_CAPOPEN_URL    = "https://m.betking.com/en-ng/my-bets/sports/open?_data=routes%2F%28%24locale%29.my-bets.sports.%24betsType"SETTLED_URL = "https://m.betking.com/en-ng/my-bets/sports/settled?_data=routes%2F%28%24locale%29.my-bets.sports.%24betsType"MYBETS_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Dnt":             "1",    "Sec-Gpc":         "1",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "same-origin",    "Priority":        "u=0",    "Te":              "trailers",}def _get_supabase():    import os    from supabase import create_client    base   = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))    config = {}    with open(os.path.join(base, "db.txt"), "r") as f:        for line in f:            line = line.strip()            if not line or line.startswith("#"):                continue            if "=" in line:                key, _, value = line.partition("=")                config[key.strip()] = value.strip().strip('"')    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def _get_cookie():    sb  = _get_supabase()    row = sb.table("betking").select("cookie").eq("id", 1).single().execute()    return row.data["cookie"]def _today_str() -> str:    return datetime.now(timezone.utc).strftime("%Y-%m-%d")def _day_label() -> str:    today = _today_str()    y, m, d = today.split("-")    return f"{int(d)}/{int(m)}/{y}"async def _fetch_open(headers: dict) -> dict:    try:        async with httpx.AsyncClient(http2=True, timeout=15.0, follow_redirects=False) as client:            resp = await client.get(                OPEN_URL,                headers={**headers, "Referer": "https://m.betking.com/en-ng/my-bets/sports/settled"},            )            if resp.status_code in (401, 301):                return {"error": str(resp.status_code)}            if not resp.text or not resp.text.strip():                return {"error": "session_expired"}            data = resp.json()            return data if isinstance(data, dict) else {"error": "session_expired"}    except Exception as e:        return {"error": f"exception:{e}"}async def _fetch_settled(headers: dict) -> dict:    try:        async with httpx.AsyncClient(http2=True, timeout=15.0, follow_redirects=False) as client:            resp = await client.get(                SETTLED_URL,                headers={**headers, "Referer": "https://m.betking.com/en-ng/my-bets/sports/open"},            )            if resp.status_code in (401, 301):                return {"error": str(resp.status_code)}            if not resp.text or not resp.text.strip():                return {"error": "session_expired"}            data = resp.json()            return data if isinstance(data, dict) else {"error": "session_expired"}    except Exception as e:        return {"error": f"exception:{e}"}def _count_open(data: dict) -> int:    coupons = data.get("couponsData", {}).get("coupons", [])    return sum(1 for c in coupons if c.get("couponCode"))def _get_or_create_row(sb, day_str: str) -> dict:    """Fetch today's tracker row, creating it fresh if it's a new day or missing."""    row = sb.table("sp_tracker").select("*").eq("name", TRACKER_NAME).execute()    if not row.data:        sb.table("sp_tracker").insert({            "name":    TRACKER_NAME,            "max":     _dynamic_max(0),            "played":  0,            "win":     0,            "lost":    0,            "day":     day_str,            "bet_ids": "",        }).execute()        return {"win": 0, "lost": 0, "played": 0, "day": day_str, "bet_ids": "", "max": _dynamic_max(0)}    existing = row.data[0]    if existing.get("day") != day_str:        # New day — reset everything including bet_ids        sb.table("sp_tracker").update({            "win":     0,            "lost":    0,            "played":  0,            "max":     _dynamic_max(0),            "day":     day_str,            "bet_ids": "",        }).eq("name", TRACKER_NAME).execute()        return {"win": 0, "lost": 0, "played": 0, "day": day_str, "bet_ids": "", "max": _dynamic_max(0)}    return existingdef _process_settled(data: dict, known_ids: set) -> tuple[int, int, list]:    """    Walk today's settled coupons. Skip betIds already in known_ids.    Returns (new_wins, new_losses, new_bet_ids).    """    today   = _today_str()    coupons = data.get("couponsData", {}).get("coupons", [])    new_wins    = 0    new_losses  = 0    new_bet_ids = []    for c in coupons:        settled = c.get("settledDate", "")        if not settled.startswith(today):            continue        bet_id = c.get("betId")        if not bet_id or bet_id in known_ids:            continue        state = c.get("betFinalState")        if state in (1, 5):            new_wins += 1        elif state == 3:            new_losses += 1        else:            continue  # not yet settled        new_bet_ids.append(str(bet_id))        known_ids.add(bet_id)    return new_wins, new_losses, new_bet_idsasync def check_can_bet() -> bool:    """    Returns True if betting is allowed, False if blocked.    Fires open + settled requests in parallel, updates sp_tracker.    """    try:        cookie = _get_cookie()    except Exception as e:        print(f"[betlist] cookie err : {e}")        return False    headers = {**MYBETS_HEADERS, "Cookie": cookie}    print(f"[betlist] checking   : open bets + settled")    open_task, settled_task = await asyncio.gather(        _fetch_open(headers),        _fetch_settled(headers),    )    open_err    = open_task.get("error")    settled_err = settled_task.get("error")    if open_err or settled_err:        err = open_err or settled_err        if err in ("401", "301", "session_expired"):            print(f"[betlist] session    : expired - attempting re-login")            import sys, os            sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))            from login import login            await login()        else:            print(f"[betlist] fetch err  : {err}")        return False    open_count = _count_open(open_task)    try:        sb      = _get_supabase()        day_str = _day_label()        row     = _get_or_create_row(sb, day_str)        # Parse already-known betIds from DB        raw_ids    = row.get("bet_ids") or ""        known_ids  = set(int(x) for x in raw_ids.split(",") if x.strip())        # Find new settled bets not yet recorded        new_wins, new_losses, new_bet_ids = _process_settled(settled_task, known_ids)        wins   = row.get("win",  0) + new_wins        losses = row.get("lost", 0) + new_losses        played = wins + losses        # Build updated bet_ids string        updated_ids = raw_ids        if new_bet_ids:            updated_ids = ",".join(filter(None, [raw_ids] + new_bet_ids))            print(f"[betlist] new bets   : {len(new_bet_ids)} recorded")        max_today = _dynamic_max(losses)        sb.table("sp_tracker").update({            "win":     wins,            "lost":    losses,            "played":  played,            "max":     max_today,            "bet_ids": updated_ids,        }).eq("name", TRACKER_NAME).execute()        print(f"[betlist] tracker    : updated")    except Exception as e:        print(f"[betlist] tracker err: {e}")        wins      = 0        losses    = 0        played    = 0        max_today = _dynamic_max(0)    print(f"[betlist] open bets  : {open_count} / {MAX_OPEN_BETS}")    print(f"[betlist] today      : played={played} | win={wins} | lost={losses} | max={max_today}")    if open_count >= MAX_OPEN_BETS:        print(f"[betlist] blocked    : max open bets reached ({open_count})")        return False    if played >= max_today:        print(f"[betlist] blocked    : daily max played reached ({played}/{max_today})")        return False    return True